// SPDX-License-Identifier: Apache-2.0
//! Spark datetime patterns against Spark 4.2
//! (`tests/fixtures/spark-4.2.0/datetime-patterns.json`, generated by
//! `tests/scripts/gen_datetime_pattern_goldens.py`): `date_format` of fixed
//! instants in a UTC and a `+05:30` session, and `to_timestamp`,
//! `to_timestamp_ntz` and the CSV reader's date and strict
//! `TIMESTAMP_NTZ` parsing (`from_csv`) of formatted, hand-written and mutated
//! strings. A pattern Spark rejects must fail with Spark's error class.
//! Strings naming a region zone resolve against the bundled database and
//! compare as values; an unresolvable one reads as no match, as in Spark's
//! lenient readers.
#![forbid(unsafe_code)]

use krishiv_common::error::{ErrorClass, KrishivError};
use krishiv_kernels::cast::FixedOffset;
use krishiv_kernels::datetime_pattern::{DateTimePattern, Purpose, Zone};
use serde_json::Value;

type R = Result<(), Box<dyn std::error::Error>>;

fn fixture() -> Result<Value, Box<dyn std::error::Error>> {
    let path = krishiv_testkit::tests_dir().join("fixtures/spark-4.2.0/datetime-patterns.json");
    Ok(serde_json::from_str(&std::fs::read_to_string(path)?)?)
}

/// The class name a golden error records, if the value is an error.
fn golden_error(v: &Value) -> Option<&str> {
    v.get("error").and_then(Value::as_str)
}

fn check_rejected(pattern: &str, got: &KrishivError, want: &str, failures: &mut Vec<String>) {
    if got.error_class().name() != want {
        failures.push(format!(
            "{pattern:?}: rejected with {}, Spark {want}",
            got.error_class().name()
        ));
    }
}

#[test]
fn formatting_matches_spark() -> R {
    let f = fixture()?;
    let instants: Vec<i64> = f["instants"]
        .as_array()
        .ok_or("instants")?
        .iter()
        .map(|v| v.as_i64().ok_or("instant"))
        .collect::<Result<_, _>>()?;
    let zones = [
        ("utc", "UTC", FixedOffset(0)),
        ("plus0530", "+05:30", FixedOffset(19_800)),
    ];
    let (mut failures, mut checked) = (Vec::new(), 0);
    for case in f["format"].as_array().ok_or("format")? {
        let pattern = case["pattern"].as_str().ok_or("pattern")?;
        let compiled = DateTimePattern::new(pattern, Purpose::Format);
        for (key, id, rules) in &zones {
            let want = &case[*key];
            match (&compiled, golden_error(want)) {
                (Err(e), Some(class)) => check_rejected(pattern, e, class, &mut failures),
                (Ok(_), Some(class)) => {
                    failures.push(format!("{pattern:?}: compiled, Spark {class}"));
                }
                (Err(e), None) => {
                    failures.push(format!("{pattern:?}: rejected ({e}), Spark formats"));
                }
                (Ok(p), None) => {
                    let values = want.as_array().ok_or("values")?;
                    for (m, v) in instants.iter().zip(values) {
                        checked += 1;
                        let got = p.format_timestamp(*m, Zone { id, rules });
                        match (got, v.as_str()) {
                            (Ok(g), Some(w)) if g == w => {}
                            (got, w) => failures
                                .push(format!("{pattern:?} {key} {m}: got {got:?}, Spark {w:?}")),
                        }
                    }
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {checked} differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(checked > 1500, "only {checked} values checked");
    Ok(())
}

/// A golden value: `Some(n)`, `None` for NULL or a row Spark failed (a
/// year out of range, which Krishiv reads as no match).
fn value(v: &Value) -> Option<i64> {
    v.as_i64()
}

#[test]
fn parsing_matches_spark() -> R {
    let f = fixture()?;
    let (mut failures, mut checked, mut regions) = (Vec::new(), 0, 0);
    let utc = FixedOffset(0);
    let plus0530 = FixedOffset(19_800);
    for case in f["parse"].as_array().ok_or("parse")? {
        let pattern = case["pattern"].as_str().ok_or("pattern")?;
        let compiled = DateTimePattern::new(pattern, Purpose::Parse);
        let p = match (compiled, golden_error(&case["ts_utc"])) {
            (Err(e), Some(class)) => {
                check_rejected(pattern, &e, class, &mut failures);
                continue;
            }
            (Ok(_), Some(class)) => {
                failures.push(format!("{pattern:?}: compiled, Spark {class}"));
                continue;
            }
            (Err(e), None) => {
                failures.push(format!("{pattern:?}: rejected ({e}), Spark parses"));
                continue;
            }
            (Ok(p), None) => p,
        };
        let strings = case["strings"].as_array().ok_or("strings")?;
        for (i, s) in strings.iter().enumerate() {
            let s = s.as_str().ok_or("string")?;
            let runs: [(&str, Result<Option<i64>, KrishivError>); 5] = [
                ("ts_utc", p.parse_timestamp(s, &utc)),
                ("ts_plus0530", p.parse_timestamp(s, &plus0530)),
                ("ntz", p.parse_local(s, true)),
                ("ntz_strict", p.parse_local(s, false)),
                ("date", p.parse_date(s).map(|d| d.map(i64::from))),
            ];
            for (key, got) in runs {
                let want = value(&case[key][i]);
                match got {
                    Ok(got) => {
                        checked += 1;
                        if got != want {
                            failures.push(format!(
                                "{pattern:?} {s:?} {key}: got {got:?}, Spark {want:?}"
                            ));
                        }
                    }
                    Err(e) if e.error_class() == ErrorClass::KrishivUnsupportedFeature => {
                        regions += 1;
                    }
                    Err(e) => failures.push(format!("{pattern:?} {s:?} {key}: {e}")),
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {checked} differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(checked > 3000, "only {checked} values checked");
    // Region zones resolve against the bundled database, so nothing should
    // need it counted out anymore.
    assert_eq!(regions, 0, "{regions} strings needed the tz database");
    Ok(())
}
